/* Relationship edges describe saved memberships, never inferred delivery dependencies. */
window.ProjectTeamMap=(()=>{
 function model({project,teams,members,issues}){
  const tasks=issues.filter(t=>t.projectId===project.id),team=teams.find(t=>t.id===project.teamId),teamIds=new Set(team?.memberIds||[]),directIds=new Set(project.memberIds||[]);
  const ids=new Set([...teamIds,...directIds,project.managerId,...tasks.map(t=>t.assigneeId)].filter(Boolean));
  const people=members.filter(m=>ids.has(m.id)).map(member=>({member,roles:[...(member.id===project.managerId?['Project manager']:[]),...(directIds.has(member.id)?['Project member']:[]),...(teamIds.has(member.id)?['Team member']:[]),...(tasks.some(t=>t.assigneeId===member.id)?['Task assignee']:[])],open:tasks.filter(t=>t.assigneeId===member.id&&t.status!=='Done').length,total:tasks.filter(t=>t.assigneeId===member.id).length,inTeam:teamIds.has(member.id)})).sort((a,b)=>Number(b.inTeam)-Number(a.inTeam)||a.member.name.localeCompare(b.member.name));
  return {project,team,people,tasks,unassigned:tasks.filter(t=>!t.assigneeId&&t.status!=='Done').length};
 }
 function mount(container,data,{avatar}){
  const m=model(data);let zoom=1,panX=0,panY=0,drag=null;
  const teamPeople=m.people.filter(p=>p.inTeam),others=m.people.filter(p=>!p.inTeam),height=Math.max(480,m.people.length*122+110),width=1000;
  const root={x:30,y:height/2-50},team={x:350,y:Math.max(62,teamPeople.length*122/2+35)-50};
  const people=m.people.map((p,i)=>({...p,x:710,y:60+i*122}));
  const path=(a,b,bypass=false)=>{const start=a.x+240,y=a.y+49,end=b.x,ey=b.y+49;return bypass?`M ${start} ${y} C ${start+25} ${y}, 300 ${height-22}, 550 ${height-22} S 650 ${ey}, ${end} ${ey}`:`M ${start} ${y} C ${(start+end)/2} ${y}, ${(start+end)/2} ${ey}, ${end} ${ey}`};
  const edge=(a,b,direct=false)=>`<path class="${direct?'tm-direct':''}" d="${path(a,b,direct&&!!m.team)}"/>`;
  const edges=(m.team?edge(root,team):'')+people.map(p=>edge(p.inTeam&&m.team?team:root,p,!p.inTeam)).join('');
  const node=(cls,pos,content)=>`<article class="tm-node ${cls}" style="left:${pos.x}px;top:${pos.y}px">${content}</article>`;
  container.innerHTML=`<section class="team-map"><div class="work-heading"><div><h2>Project Team Relationship Map</h2><p class="muted">Project ownership, team membership, and task assignments</p></div><button class="secondary" data-project-edit="${esc(m.project.id)}">Manage relationships</button></div><div class="tm-metrics"><span><b>${m.team?1:0}</b> assigned team</span><span><b>${m.people.length}</b> contributors</span><span><b>${m.tasks.length}</b> tasks</span><span><b>${m.unassigned}</b> open tasks unassigned</span></div><div class="tm-viewport" tabindex="0" aria-label="Project team relationship map. Drag the background to pan; use zoom controls or arrow keys to move."><div class="tm-stage" style="width:${width}px;height:${height}px"><svg width="${width}" height="${height}" aria-hidden="true">${edges}</svg>${node('tm-project',root,`<small>PROJECT · ${esc(ProjectAPI.projectKey(m.project))}</small><strong>${esc(m.project.name)}</strong><span>${esc(m.project.status)} · ${m.tasks.filter(t=>t.status!=='Done').length} open tasks</span>`)}${m.team?node('tm-team',team,`<small>ASSIGNED TEAM</small><button class="task-title" data-team-edit="${esc(m.team.id)}">${esc(m.team.name)}</button><span>${teamPeople.length} members · Edit team ↗</span>`):''}${people.map(p=>node('tm-member',p,`<div class="tm-person">${avatar(p.member)}<button class="task-title" data-member-profile="${esc(p.member.id)}">${esc(p.member.name)}</button></div><small>${esc(p.roles.join(' · '))}${p.member.active===false?' · Inactive':''}</small><span>${p.open} open / ${p.total} assigned tasks</span>`)).join('')}${!people.length?'<p class="tm-empty" style="left:350px;top:210px">No contributors yet. Assign a team, project members, or task owners to build this map.</p>':''}</div></div><div class="tm-bottom"><div class="tm-controls" aria-label="Map controls"><button class="secondary" data-map-zoom="in" aria-label="Zoom in relationship map">+</button><button class="secondary" data-map-zoom="out" aria-label="Zoom out relationship map">−</button><button class="secondary" data-map-fit>Fit view</button><button class="secondary" data-map-reset>100%</button><output aria-live="polite" class="tm-scale"></output></div><div class="tm-legend"><span><i></i>Assigned team / team membership</span><span><i class="tm-dashed"></i>Other project contributors</span></div></div><p class="muted tm-help">Drag the background to pan. Click a member to see their projects, tasks, and history. Relationships update when project, team, or task assignments change.</p><details class="tm-list"><summary>View relationships as a table</summary><div class="bug-table-wrap"><table class="bug-table"><thead><tr><th>Member</th><th>Relationship</th><th>Open tasks</th><th>Assigned tasks</th></tr></thead><tbody>${m.people.map(p=>`<tr><td><button class="text-btn" data-member-profile="${esc(p.member.id)}">${esc(p.member.name)}</button></td><td>${esc(p.roles.join(', '))}</td><td>${p.open}</td><td>${p.total}</td></tr>`).join('')||'<tr><td colspan="4">No contributors yet.</td></tr>'}</tbody></table></div></details></section>`;
  const viewport=container.querySelector('.tm-viewport'),stage=container.querySelector('.tm-stage'),scale=container.querySelector('.tm-scale');
  function draw(){stage.style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`;scale.value=Math.round(zoom*100)+'%';scale.textContent=scale.value}
  function fit(){zoom=Math.max(.01,Math.min(1,(viewport.clientWidth-24)/width,(viewport.clientHeight-24)/height));panX=(viewport.clientWidth-width*zoom)/2;panY=(viewport.clientHeight-height*zoom)/2;draw()}
  function setZoom(next){next=Math.max(.01,Math.min(2,next));const cx=viewport.clientWidth/2,cy=viewport.clientHeight/2;panX=cx-(cx-panX)*next/zoom;panY=cy-(cy-panY)*next/zoom;zoom=next;draw()}
  container.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mapZoom)setZoom(zoom*(b.dataset.mapZoom==='in'?1.25:.8));if(b.hasAttribute('data-map-fit'))fit();if(b.hasAttribute('data-map-reset'))setZoom(1)});
  viewport.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button,a'))return;drag={x:e.clientX,y:e.clientY,px:panX,py:panY,id:e.pointerId};viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging')});
  viewport.addEventListener('pointermove',e=>{if(!drag)return;panX=drag.px+e.clientX-drag.x;panY=drag.py+e.clientY-drag.y;draw()});
  const end=()=>{drag=null;viewport.classList.remove('dragging')};viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);viewport.addEventListener('lostpointercapture',end);
  viewport.addEventListener('keydown',e=>{if(e.target!==viewport)return;const moves={ArrowLeft:[40,0],ArrowRight:[-40,0],ArrowUp:[0,40],ArrowDown:[0,-40]};if(moves[e.key]){e.preventDefault();panX+=moves[e.key][0];panY+=moves[e.key][1];draw()}if(e.key==='+'||e.key==='='){e.preventDefault();setZoom(zoom*1.25)}if(e.key==='-'){e.preventDefault();setZoom(zoom*.8)}if(e.key==='Home'){e.preventDefault();fit()}});
  fit();
 }
 return {model,mount};
})();
